(() => {
 'use strict';const RI=window.RI,esc=RI.esc;
 RI.registerPage('studio',{title:'آمادگی انتشار',render(){
  const ready=RI.readiness(),all=RI.pageKinds().flatMap(kind=>ready[kind]),required=all.filter(x=>x.req),missing=required.filter(x=>!x.done).length;
  const summary='<section class="studio-overview" aria-label="وضعیت آمادگی صفحه‌ها"><div><span class="studio-overview__icon">'+RI.icon(missing?'edit':'check')+'</span><h2>'+(missing?'صفحه‌هایت در مسیر انتشارند':RI.workspaceSlot===3?'صفحهٔ لینک آماده است':'هر دو صفحه آماده‌اند')+'</h2><p>'+(missing?'کمبودهای پایه را همین‌جا پیدا و تکمیل کن؛ جزئیات تکمیلی را هر وقت خواستی اضافه کن.':'پایه‌های انتشار کامل است؛ نسخهٔ عمومی را از نوار بالای صفحه منتشر یا تازه کن.')+'</p></div><dl>'+[['پایه‌های تکمیل‌شده',RI.fa(required.length-missing)+' از '+RI.fa(required.length)],['نیاز به تکمیل',RI.fa(missing)],['جزئیات تکمیلی',RI.fa(all.filter(x=>!x.req&&x.done).length)]].map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+value+'</dd></div>').join('')+'</dl></section>';
  return RI.pageHead({title:'آمادگی انتشار'})+summary+RI.pageKinds().map(kind=>'<section class="studio-ready"><h2>'+RI.icon(kind==='resume'?'resume':'link')+(kind==='resume'?'رزومه':'صفحهٔ لینک‌ها')+'</h2>'+RI.completionStrip(kind)+[['پایهٔ انتشار',true],['جزئیات تکمیلی',false]].map(([label,req])=>'<details class="allsteps" '+(req?'open':'')+'><summary>'+label+RI.icon('chevD')+'</summary><ul class="chklist">'+ready[kind].filter(x=>!!x.req===req).map(x=>'<li class="chk '+(x.done?'is-done':'')+'"><span class="chk__tick">'+RI.icon(x.done?'check':req?'edit':'plus')+'</span><span class="chk__t">'+esc(x.label)+'</span>'+(!x.done?'<a class="btn btn--ghost btn--sm" href="'+RI.routeUrl(x.route,{step:x.step,tab:x.tab,anchor:x.anchor})+'" data-go="'+x.route+'" '+(x.step?'data-step="'+x.step+'"':'')+(x.tab?' data-tab="'+x.tab+'"':'')+(x.anchor?' data-anchor="'+x.anchor+'"':'')+'>تکمیل'+RI.icon('chevL')+'</a>':'')+'</li>').join('')+'</ul></details>').join('')+'</section>').join('');
 }});
})();
